import{R as e,e as n,f as o,U as r}from"./chunks/framework.ywem4qy5.js";const u=JSON.parse('{"title":"Mercury (by Connective)","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/mercury.md","filePath":"integrations/crm/mercury.md","lastUpdated":1775908585000}'),i={name:"integrations/crm/mercury.md"};function a(l,t,s,c,h,g){return n(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="mercury-by-connective" tabindex="-1">Mercury (by Connective) <a class="header-anchor" href="#mercury-by-connective" aria-label="Permalink to &quot;Mercury (by Connective)&quot;">​</a></h1><p>Follow the below steps to connect to the Connective Mercury API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Mercury as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-connective-mercury-api" tabindex="-1">Step 2. Connect to the Connective Mercury API <a class="header-anchor" href="#step-2-connect-to-the-connective-mercury-api" aria-label="Permalink to &quot;Step 2. Connect to the Connective Mercury API&quot;">​</a></h3><ol><li>Go to <a href="https://www.connective.com.au/" target="_blank">Connective</a> and login to your Mercury account.</li><li>In the top menu, click the <strong>Admin</strong> tab.</li><li>In the left-hand sidebar menu, click the <strong>Integrations</strong> tab.</li><li>Copy the <strong>API Key</strong> from Mercury and paste in the <strong>API Key</strong> field in Formie.</li><li>Copy the <strong>API Token</strong> from Mercury and paste in the <strong>API Token</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const m=e(i,[["render",a]]);export{u as __pageData,m as default};
